/** Replace only canonical path tokens and hashes transitively derived from them. */
export function instantiatePr39OriginRouteTemplate(rawTemplate, { dataRoot, origin, target }) {
  if (!Object.values(PR39_ORIGIN_ROUTE_TEMPLATES).includes(rawTemplate)) throw new Error('unknown PR39 template');
  const manifest = JSON.parse(rawTemplate); const activeTurnId = manifest.activeTurnId ?? manifest.parentTurnId;
  const replacements = Object.freeze({
    DATA_ROOT: dataRoot, ORIGIN: origin, TARGET: target,
    ORIGIN_WORKSPACE_HASH: hash(origin), TARGET_WORKSPACE_HASH: hash(target),
    GLOBAL_KEY: digest(manifest.sessionId), ORIGIN_INDEX_KEY: digest(manifest.sessionId, origin),
    TARGET_INDEX_KEY: digest(manifest.sessionId, target), CALLER_DIGEST: hash('pr39-' + manifest.name + '-caller-context'),
    ROUTE_KEY: digest('executor-route', manifest.sessionId, manifest.childTurnId),
    FORWARD_KEY: digest('forward', manifest.sessionId, manifest.childTurnId),
    EXECUTOR_KEY: digest('executor', manifest.agentId),
    PREPARATION_KEY: digest(manifest.sessionId, activeTurnId, target, 'rescue'),
    PENDING_KEY: digest(manifest.sessionId, target, 'rescue'),
    BINDING_PARTITION_KEY: digest('rescue-binding-session-v1', manifest.sessionId, target),
    BINDING_KEY: digest('rescue-binding-v1', manifest.sessionId, manifest.agentId, target),
    OWNER_DIRECTORY: hash('zcode-owner-index-v1\0' + manifest.sessionId),
    OWNER_ID: digest('zcode-owner-v1', manifest.sessionId),
  });
  const substitute = (template) => {
    const replaced = template.replace(/\{\{([A-Z_]+)\}\}/gu, (token, name) => {
      if (!Object.hasOwn(replacements, name)) throw new Error('unknown PR39 token: ' + token);
      return replacements[name];
    });
    if (/\{\{[^}]+\}\}/u.test(replaced)) throw new Error('unresolved PR39 token');
    return replaced;
  };
  const records = manifest.records.map((record) => Object.freeze({
    path: join(dataRoot, substitute(record.path)),
    bytes: substitute(record.bytes),
    classification: record.classification,
  }));
  return Object.freeze({
    ...manifest, originDirectory: join(dataRoot, 'workspaces', replacements.ORIGIN_WORKSPACE_HASH),
    targetDirectory: join(dataRoot, 'workspaces', replacements.TARGET_WORKSPACE_HASH),
    records: Object.freeze(records),
  });
}
function digest(...values) { return hash('[' + values.map(jsonString).join(',') + ']'); }
function hash(value) { return createHash('sha256').update(value).digest('hex'); }
function jsonString(value) {
  const quote = String.fromCharCode(34); const slash = String.fromCharCode(92); let encoded = quote;
  for (const character of value) {
    const code = character.codePointAt(0);
    if (character === quote) encoded += slash + quote; else if (character === slash) encoded += slash + slash;
    else if (code <= 31) { const short = { 8: 'b', 9: 't', 10: 'n', 12: 'f', 13: 'r' }[code]; encoded += slash + (short ?? 'u' + code.toString(16).padStart(4, '0')); }
    else encoded += character;
  }
  return encoded + quote;
}
